function UIActivityPromoterDialog:__init()
    self.promoterSchedulesVO = nil
    self.isCanReceive = false
    self.animMapList  = {}
end

function UIActivityPromoterDialog:__delete()

end

function UIActivityPromoterDialog:Awake()
    SetButtonAction(self.InviteFriendsHelpBtn, Bind(self, self._OnClick_InviteFriendsHelpBtn))
    SetButtonAction(self.ReceiveBtn, Bind(self, self._OnClick_ReceiveBtn))
    ---
    self.eventRefresh_ = Events.AddListener(Constants.EventNames.PromoterRefresh, Bind(self, self.DoRefresh))
end



function UIActivityPromoterDialog:OnDestroy()

    if self.eventRefresh_ then
        Events.RemoveListener(Constants.EventNames.PromoterRefresh, self.eventRefresh_)
        self.eventRefresh_ = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end




-- 刷新入口:
function UIActivityPromoterDialog:Refresh(activityDojo, signData)
    self.activityDt   = activityDojo
    self.activityUuid = checkInt(activityDojo.id)
    self.signData = signData
    ---
    self:DoRefresh()
end



function UIActivityPromoterDialog:DoRefresh()

    GameUtils.Request( "Activity/spread", {activityUuid = self.activityUuid}, function(request, response)
        if checkNumber(response.errCode) == 0 then

            self.spreadDojoData = response.data
            if isNull(self.spreadDojoData.skinSpreadConf) then 
                printError("后端数据异常 Activity/spread 中没找到 skinSpreadConf ")
                return
            end 

            self.promoterSchedulesVO = UIActivityPromoterUtils.GetActivityPromoterSchedulesVO( self.spreadDojoData.skinSpreadConf.id )

            SetButtonAction(self.BtnDesc, function()
                CfUtils.ShowModuleToast(self.promoterSchedulesVO.ruleID)
            end)

            local isFreeRewardsActive = self.spreadDojoData.isDrawFreeRewards ~= 1
            if isFreeRewardsActive then 
                SetButtonAction(self.BtnFreeReward, function()
                    self:OnClickBtnFreeReward()
                end)
            end 
            self:RefreshFreeReward( isFreeRewardsActive )

            -- update view
            self:RefreshView()
            self:UpdateRedPoint( isFreeRewardsActive )
        end
    end)
end



function UIActivityPromoterDialog:RefreshView()
    if not self.activityDt or next(self.activityDt) == nil then
        return
    end

    -- 右侧 整个 "活动时间" 一块都隐藏;
    KTool.SetActive( self.TimeGroup, false )

    -- 左侧角色皮肤 (大半身像)
    local skinId = checkNumber(self.spreadDojoData.skinSpreadConf.appearanceId) -- 10202102
    self.BossDrawingNode:Execute( skinId )

    -- 左侧 SSR 组件UI内容 + 按钮:
    self:InitCommonBtnRoleNameNode()

    -- 左侧 "收集进度" 节点
    self:DrawFillNode()


    -- 左侧, "领取外观按钮":
    if self.isCanReceive == true then 
        self.ReceiveBtn:ResetFontStyle("B25", localize("前往兑换"))
        CfUtils.SetActive( self.ReceiveBtnFX, true )
    else
        self.ReceiveBtn:ResetFontStyle("B18", localize("前往兑换"))
        CfUtils.SetActive( self.ReceiveBtnFX, false )
    end

    -- 右侧 "邀请好友助力" 按钮上方的 奖励图标
    if self.spreadDojoData.isShare == 0 then 
        CfUtils.SetActive( self.InviteFriendsHelpReward, true )
        self:DrawInviteFriendsHelpReward()
    else 
        CfUtils.SetActive( self.InviteFriendsHelpReward, false )
    end 

    

    self:RefreshReward()

    -- "活动时间" 下方的一段小字
    CfUtils.FillText(self.Text, string.trim(self.activityDt.detail) ~= "" and self.activityDt.detail or "")
    
end



-- 初始化 画面左侧 SSR 区域的 ui元素 + 按钮:
function UIActivityPromoterDialog:InitCommonBtnRoleNameNode()

    local skinId = self.spreadDojoData.skinSpreadConf.appearanceId
    --skinId = 10300602
    ------ 
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(skinId)
    if not isNull(goodsVo) then
        local idType = GoodsUtils.GetIdType(goodsVo.id)
        if idType == Constants.IDType.CardSkin then
            ---@type CommonBtnRoleNameNode
            local env = CfUtils.GetLuaScr(self.BtnRoleNameNode.gameObject, "Game.UI.Common.CommonBtnRoleNameNode")
            if env then
                env:RefreshSelf(goodsVo.id, goodsVo.quality, function()
                    --CfUtils.CookieSave("UIWelfareMainDialog_Index",self.curIndex)
                end, true)
            end
            --KTool.SetActive(self.BtnRoleGoods.gameObject,true)
        end
    end
end


function UIActivityPromoterDialog:OnClickBtnFreeReward()
    GameUtils.Request( "Activity/spreadDrawFreeRewards", {activityUuid = self.activityUuid }, function(request, response)
        if checkNumber(response.errCode) == 0 then
            --printError("data = " .. table.dump(response.data) )

            Events.Broadcast(Constants.EventNames.PromoterRefresh)
            -- 领取 每周免费奖励 数据, 
            GoodsUtils.DrawRewards( response.data.rewards )
            -- 播放窗口动画:
            UIModule.OpenDialog({ 
                id = Constants.UITypeIds.UICommonRewardPop, 
                parameters = { rewards = response.data.rewards } 
            })
        end
    end)
end


-- 刷新 BtnFreeReward 的视觉状态:
function UIActivityPromoterDialog:RefreshFreeReward( isActive_ )
    local anmRootTF = self.BtnFreeReward.transform:Find("AnmRoot")
    local redPointTF = self.BtnFreeReward.transform:Find("AnmRoot/redPoint")
    local fxTF = self.BtnFreeReward.transform:Find("AnmRoot/FX_glow2")
    local imgSymbolTF = self.BtnFreeReward.transform:Find("AnmRoot/ImgSymbol")
    CfUtils.SetActive( redPointTF.gameObject, isActive_ )
    CfUtils.SetActive( fxTF.gameObject, isActive_ )
    CfUtils.PlayAnimation( anmRootTF.gameObject, checkBool(isActive_) and animName_freeReward_highLight or animName_freeReward_default )
    CfUtils.SetUISwitchImage( imgSymbolTF.gameObject, isActive_ and 2 or 1 )
end


-- 左侧, "收集进度" 节点
function UIActivityPromoterDialog:DrawFillNode()
    assert( isNotNull(self.FillNode) )
    if isNull(self.promoterSchedulesVO) or isNull(self.spreadDojoData) then 
        printError( "promoterSchedulesVO 或 spreadDojoData 没准备好" )
        return
    end 
    ---

    --local progress = GoodsUtils.GetThingNo(self.promoterSchedulesVO.costItem) -- 走背包版, 但是背包数据可能没有被及时更新
    local progress = checkNumber( self.spreadDojoData.num ) -- 走 dojo版
    local targetNum = self.spreadDojoData.skinSpreadConf.costNum

    self.isCanReceive = (progress >= targetNum)
    --self.isCanReceive = true

    -- find Node:
    local TextNumTF = self.FillNode.transform:Find("TextNum")
    local ProgressBarTF = self.FillNode.transform:Find("ProgressBar")
    local slider = KTool.GetComponent(ProgressBarTF.gameObject, typeof(Slider))
    local ImgIcon = self.FillNode.transform:Find("ImgIcon")

    CfUtils.FillText( TextNumTF.gameObject, string.format("<size=38><color=#65ffe3>%s</color></size>/%s", progress, targetNum) )
    slider.value = checkNumber( progress/targetNum )

    -- 绘制 道具 "外观助力券"
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(self.promoterSchedulesVO.costItem)
    CfUtils.FillImage(ImgIcon, ActivityUtils.GetImageFullPath(goodsVo.photoPath ,false))


    -- !!! 因为这个券的数据 不光有 DrawRewards() 添加的, 还有其它玩家点击链接增加的值, 这部分值无法累加到背包中; 只能在此手动改写值:
    ---@type BackpackComponent
    local backpackComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.BackpackComponent)
    backpackComp.backpack[tostring(self.promoterSchedulesVO.costItem)] = progress

end



