function UIActivityPromoterDialog:RefreshReward()
    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(#self:GetSpreadTasks(), Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(self.LoopListCell,#self:GetSpreadTasks())
    end
end



function UIActivityPromoterDialog:GetSpreadTasks()
    return self.spreadDojoData.task
end


function UIActivityPromoterDialog:GetItemShowNum()
    return checkInt(self.itemShowNum)
end


function UIActivityPromoterDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cellNode = listView:NewListViewItem("Cell")
    ---@type UIActivityTotalTopupCellNode
    local nodeEnv  = CfUtils.GetLuaScr(cellNode, "Game.UI.ActivityMainDialog.UIActivityPromoterCell")
    local index1Based = index + 1

    local spreadTasks  = self:GetSpreadTasks()

    if nodeEnv then

        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cellNode.CachedRectTransform.rect.height + cellNode.Padding
            self.itemShowNum = math.ceil(listView.ViewPortHeight / cellSizeH)
        end

        if not self.animMapList[index1Based] and (index1Based-1) <= self:GetItemShowNum() then
            self.animMapList[index1Based] = true
            nodeEnv:PlayFadeInAnim(index1Based-1)
        else
            nodeEnv:PlayInitAnim()
        end

        nodeEnv:Refresh(spreadTasks[index1Based] , index1Based, self)
    end

    return cellNode
end



-- 刷新 活动页面 左侧条目 的红点
function UIActivityPromoterDialog:UpdateRedPoint( isFreeRewardsActive_ )
    local isOpenRedPoint   = false
    local spreadTasks  = self:GetSpreadTasks()
    for _,taskDojo in pairs(spreadTasks) do
        if taskDojo.status == 1 then 
            isOpenRedPoint = true
            break
        end 
    end

    isOpenRedPoint = isOpenRedPoint or (isFreeRewardsActive_)
    ActivityUtils.UpdateActivityMainRedPointState(self.activityDt.id, isOpenRedPoint and 0 or -1)
end




return UIActivityPromoterDialog
